"558 :     public String asPath() {
559 :         if (id != null) {
560 :             return "id('" + escape(id) + "')";
561 :         }
562 : 
563 :         StringBuffer buffer = new StringBuffer();
564 :         if (parent != null) {
565 :             buffer.append(parent.asPath());
566 :         }
567 :         switch (node.getNodeType()) {
568 :             case Node.ELEMENT_NODE :
569 :                 // If the parent pointer is not a DOMNodePointer, it is
570 :                 // the parent's responsibility to produce the node test part
571 :                 // of the path
572 :                 if (parent instanceof DOMNodePointer) {
573 :                     if (buffer.length() == 0
574 :                             || buffer.charAt(buffer.length() - 1) != '/') {
575 :                         buffer.append('/');
576 :                     }
577 :                     String ln = DOMNodePointer.getLocalName(node);
578 :                     String nsURI = getNamespaceURI();
579 :                     if (nsURI == null) {
580 :                         buffer.append(ln);
581 :                         buffer.append('[');
582 :                         buffer.append(getRelativePositionByName()).append(']');
583 :                     }
584 :                     else {
585 :                         String prefix = getNamespaceResolver().getPrefix(nsURI);
586 :                         if (prefix != null) {
587 :                             buffer.append(prefix);
588 :                             buffer.append(':');
589 :                             buffer.append(ln);
590 :                             buffer.append('[');
591 :                             buffer.append(getRelativePositionByName());
592 :                             buffer.append(']');
593 :                         }
594 :                         else {
595 :                             buffer.append("node()");
596 :                             buffer.append('[');
597 :                             buffer.append(getRelativePositionOfElement());
598 :                             buffer.append(']');
599 :                         }
600 :                     }
601 :                 }
602 :             break;
603 :             case Node.TEXT_NODE :
604 :             case Node.CDATA_SECTION_NODE :
605 :                 buffer.append("/text()");
606 :                 buffer.append('[');
607 :                 buffer.append(getRelativePositionOfTextNode()).append(']');
608 :                 break;
609 :             case Node.PROCESSING_INSTRUCTION_NODE :
610 :                 buffer.append("/processing-instruction(\'");
611 :                 buffer.append(((ProcessingInstruction) node).getTarget()).append("')");
612 :                 buffer.append('[');
613 :                 buffer.append(getRelativePositionOfPI()).append(']');
614 :                 break;
615 :             case Node.DOCUMENT_NODE :
616 :                 // That'll be empty
617 :         }
618 :         return buffer.toString();
619 :     }"

